 private AppRegressionTest base;private MainActivity a;private VehicleCoordinator m;
 @Before public void start()throws Exception{base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);a=(MainActivity)f.get(base);m=VehicleCoordinator.get(a);f=VehicleCoordinator.class.getDeclaredField("signedIn");f.setAccessible(true);f.setBoolean(m,true);m.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();m.selected.vin="MAP-FIXTURE";m.snapshot=new VehicleSnapshot("Polestar 2","masked",85,312,12000,"空闲","全部关闭","全部关闭","已关闭","已上锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");}
 @After public void stop(){base.stop();}
 private Object field(String key)throws Exception{Field f=MainActivity.class.getDeclaredField(key);f.setAccessible(true);return f.get(a);}
 private void call(String key,Class<?>[] types,Object...args)throws Exception{Method f=MainActivity.class.getDeclaredMethod(key,types);f.setAccessible(true);f.invoke(a,args);}
