 @Test public void tabSwitchesAndResumeKeepTheSameMapAndWebView()throws Exception{Map<Integer,Object> reply=new HashMap<>();reply.put(2,io.github.polestarcn.companion.api.ProtoWire.concat(io.github.polestarcn.companion.api.ProtoWire.fixed32Field(1,113.125f),io.github.polestarcn.companion.api.ProtoWire.fixed32Field(2,23.125f)));m.parkedLocation=LocationSnapshot.fromReply(reply);AppPreferences.set(a,"map_backdrop","on");render();Object host=field("mapHost"),map=field("backdrop");assertNotNull(map);View web=((View)host).findViewWithTag("parking_webview");assertNotNull(web);Field page=MainActivity.class.getDeclaredField("page");page.setAccessible(true);for(int p:new int[]{1,2,0}){page.setInt(a,p);render();assertSame(host,field("mapHost"));assertSame(map,field("backdrop"));assertSame(web,((View)host).findViewWithTag("parking_webview"));}call("onPause",new Class<?>[0]);call("onResume",new Class<?>[0]);assertSame(map,field("backdrop"));assertSame(web,((View)host).findViewWithTag("parking_webview"));}
 @Test public void mapDelayUsesLastSuccessAndSupportsManualOnly()throws Exception{AppPreferences.set(a,"map_refresh_minutes","15");Field f=VehicleCoordinator.class.getDeclaredField("parkingFetchedAt");f.setAccessible(true);f.setLong(m,android.os.SystemClock.elapsedRealtime()-240000);assertEquals(660000,m.parkingRefreshDelay(),1000);AppPreferences.set(a,"map_refresh_minutes","0");assertEquals(-1,m.parkingRefreshDelay());}
 @Test public void defaultBatteryIsBoldAndGalleryLabelsHaveDayNightContrast()throws Exception{for(String theme:new String[]{"light","dark"}){AppPreferences.set(a,"theme",theme);UiSkin.set(a,UiSkin.PS_DEFAULT);render();TextView soc=a.getWindow().getDecorView().findViewWithTag("battery_soc");assertTrue(soc.getPaint().isFakeBoldText());call("vehicleArtDialog",new Class<?>[]{boolean.class},theme.equals("dark"));AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();TextView label=d.findViewById(android.R.id.content).findViewWithTag("vehicle_gallery_label");assertNotNull(label);assertEquals(theme.equals("dark")?android.graphics.Color.WHITE:android.graphics.Color.BLACK,label.getCurrentTextColor());d.dismiss();}}
 @Test public void skinChangesPreserveMapAndButtonOpacityDoesNotFadeText()throws Exception{Map<Integer,Object> reply=new HashMap<>();reply.put(2,io.github.polestarcn.companion.api.ProtoWire.concat(io.github.polestarcn.companion.api.ProtoWire.fixed32Field(1,113.125f),io.github.polestarcn.companion.api.ProtoWire.fixed32Field(2,23.125f)));m.parkedLocation=LocationSnapshot.fromReply(reply);AppPreferences.set(a,"map_backdrop","on");render();Object map=field("backdrop");for(String skin:UiSkin.pickerChoices()){UiSkin.set(a,skin);AppPreferences.set(a,"button_background_percent","40");render();assertSame(map,field("backdrop"));View nav=a.getWindow().getDecorView().findViewWithTag("bottom_nav_button");assertEquals(102,nav.getBackground().getAlpha());assertEquals(1f,nav.getAlpha(),.001f);}}
 @Test public void defaultHeroWeightCanBeReducedAndIncreased()throws Exception{UiSkin.set(a,UiSkin.PS_DEFAULT);for(String w:new String[]{"300","900"}){AppPreferences.set(a,"hero_number_weight",w);render();for(String tag:new String[]{"battery_soc","battery_range"}){TextView t=a.getWindow().getDecorView().findViewWithTag(tag);assertEquals(w.equals("900"),t.getPaint().isFakeBoldText());}}}
 @Test public void cLayoutIsSelectableAndKeepsCarProportions()throws Exception{UiSkin.set(a,UiSkin.SIMPLE_2);AppPreferences.set(a,"all_good_position","behind");AppPreferences.set(a,"all_good_lines","offset_c");render();VehicleHeroView hero=hero(a.getWindow().getDecorView());assertNotNull(hero);Method c=VehicleHeroView.class.getDeclaredMethod("offsetC");c.setAccessible(true);assertEquals(true,c.invoke(hero));android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(360,780,android.graphics.Bitmap.Config.ARGB_8888);View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(780,View.MeasureSpec.EXACTLY));root.layout(0,0,360,780);root.draw(new android.graphics.Canvas(bitmap));assertEquals(View.GONE,root.findViewWithTag("health_charge_slot").getVisibility());if(new java.io.File("/workspace/output").isDirectory())try(java.io.FileOutputStream out=new java.io.FileOutputStream("/workspace/output/beta9-C-native.png")){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();AppPreferences.set(a,"all_good_lines","one");render();assertEquals(false,c.invoke(hero(a.getWindow().getDecorView())));}
 @Test public void markerSettingsPreserveMapAndValidateDefaults()throws Exception{Map<Integer,Object> reply=new HashMap<>();reply.put(2,io.github.polestarcn.companion.api.ProtoWire.concat(io.github.polestarcn.companion.api.ProtoWire.fixed32Field(1,113.125f),io.github.polestarcn.companion.api.ProtoWire.fixed32Field(2,23.125f)));m.parkedLocation=LocationSnapshot.fromReply(reply);AppPreferences.set(a,"map_backdrop","on");render();Object map=field("backdrop");View web=((View)field("mapHost")).findViewWithTag("parking_webview");AppPreferences.set(a,"map_pin_size_percent","300");AppPreferences.set(a,"map_pin_color","#aabbcc");AppPreferences.set(a,"map_pin_focus_x","75");AppPreferences.set(a,"map_pin_focus_y","25");render();assertSame(map,field("backdrop"));assertSame(web,((View)field("mapHost")).findViewWithTag("parking_webview"));MapMarkerSettings pin=new MapMarkerSettings(a);assertEquals(300,pin.size);assertEquals("#AABBCC",pin.color);assertEquals(75,pin.focusX);assertEquals(25,pin.focusY);AppPreferences.set(a,"map_pin_color","bad');alert(1)");AppPreferences.set(a,"map_pin_size_percent","999");pin=new MapMarkerSettings(a);assertEquals("#FF6B00",pin.color);assertEquals(300,pin.size);assertFalse(web.isVerticalScrollBarEnabled());assertFalse(web.isHorizontalScrollBarEnabled());}
 private VehicleHeroView hero(View v){if(v instanceof VehicleHeroView)return (VehicleHeroView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){VehicleHeroView h=hero(((ViewGroup)v).getChildAt(i));if(h!=null)return h;}return null;}
